import type { Kysely } from "kysely";

import type { DB } from "./db.gen.ts";

/**
 * The database of the 締め (closing) module: a Kysely that sees only the tables of the closing schema (docs/adr/0025).
 * The types come from the migrations (db.gen.ts, generated by `pnpm exec nx db-types api`), so a query on the
 * table of another module does not compile. apps/api creates it in its entry file and passes it in.
 */
export type ClosingDatabase = Kysely<DB>;
